clear;clc;%clf;

d = readtable('~/data_big_snake.csv');

T = readtable('~/repos/rosbag/free_polytopes_vertices.csv')

%%

clf
hold on

x_comp = 1.6;
y_comp = 0.05;
theta_comp = -45*pi/180;


M = reshape(Occ, 200,200)';
% Get coordinates of all elements
[x, y] = meshgrid(linspace(-5,5,200));  % x: cols, y: rows

pos = [x(:) y(:)];
pos = pos*R;

% Flatten the data
x = pos(:,1);
y = pos(:,2);

In = M;
In(In ~= 0) = NaN;
In(In == 0) = 1;
v = In(:);
scatter(x+x_comp,y+y_comp,50,[50*v 168*v 82*v]/255,'d','filled', 'MarkerFaceAlpha', 0.3);
Out = M;
Out(Out ~= 100) = NaN;
Out(Out == 100) = 1;
v = Out(:);
scatter(x+x_comp,y+y_comp,50,[168*v 50*v 50*v]/255,'d','filled', 'MarkerFaceAlpha', 0.3);
Un = M;
Un(Un ~= -1) = NaN;
Un(Un == -1) = 1;
v = Un(:);
scatter(x+x_comp,y+y_comp,50,[0*v 0*v 0*v],'d','filled', 'MarkerFaceAlpha', 0.3);


inds = [47500:120000];
plot(d.x(inds), d.y(inds),'b','linewidth',3)
plot(d.graph_plan_x(inds), d.graph_plan_y(inds),'r','linewidth',3)
axis equal

% Get the first row (first timestamp)
row = T(1, :);

% Extract all variable names
varNames = T.Properties.VariableNames;

% Filter just vertex columns (exclude 'timestamp')
vertexCols = varNames(contains(varNames, 'vertex'));

% Parse how many polytopes we have
polyIds = regexp(vertexCols, 'poly_(\d+)_vertex_(\d+)', 'tokens');
polyNums = cellfun(@(x) str2double(x{1}{1}), polyIds);
uniquePolys = unique(polyNums);

% For each polytope, gather its vertices and plot
for p_ind = 1:length(uniquePolys)
    p = uniquePolys(p_ind);
    % Get all columns for this polytope
    polyColIdx = find(polyNums == p);
    polyVerts = zeros(2, length(polyColIdx)/2);  % (x,y) pairs

    % Sort by vertex index
    subIdx = cellfun(@(x) str2double(x{1}{2}), polyIds(polyColIdx));
    [~, order] = sort(subIdx);
    sortedCols = vertexCols(polyColIdx(order));

    % Read vertex values from the table
    v = row{1, sortedCols};

    % Reshape into (x,y) pairs
    polyVerts = reshape(v, 2, [])';
    
    R = [cos(theta_comp) sin(theta_comp);
        -sin(theta_comp) cos(theta_comp)];
    polyVerts = polyVerts*R;

    % Plot the patch
    patch(polyVerts(:,1)+x_comp, polyVerts(:,2)+y_comp, 'g', 'FaceAlpha', 0.2);
end

title('Polytopes at first timestamp');
xlabel('x'); ylabel('y');


axis([-2.5 3 -2 2])

